<script setup lang="ts">
import { computed, ref } from 'vue'
import { useRouter } from 'vue-router'
import { ElMessage } from 'element-plus'
import { Bell, Box, Calendar, CaretBottom, ChatDotRound, Cpu, DataLine, Document, Download, Edit, House, Lock, Monitor, Plus, Search, Setting, Tools, User, Warning } from '@element-plus/icons-vue'
import { useUserStore } from '../../stores/user'

const router = useRouter()
const userStore = useUserStore()
const activeMenu = ref('overview')
const keyword = ref('')
const statusFilter = ref('全部状态')
const changePasswordVisible = ref(false)
const passwordForm = ref({ oldPassword: '', newPassword: '', confirmPassword: '' })
const now = ref(new Date())
const timer = window.setInterval(() => { now.value = new Date() }, 1000)
window.addEventListener('beforeunload', () => window.clearInterval(timer), { once: true })

const menus = [
  { key: 'overview', label: '设备总览', icon: House },
  { key: 'devices', label: '设备台账', icon: Monitor },
  { key: 'categories', label: '设备分类', icon: Box },
  { key: 'alerts', label: '告警管理', icon: Bell, badge: '3' },
  { key: 'maintenance', label: '维修保养', icon: Tools },
  { key: 'reports', label: '统计报表', icon: DataLine },
  { key: 'settings', label: '系统设置', icon: Setting },
]
const devices = ref([
  { id: 'EQ-2026-0018', name: '数控加工中心', model: 'VMC850 · 三轴立式', category: '生产设备', location: '一号厂房 · A区', owner: '张工', status: '运行中', date: '2025-08-12' },
  { id: 'EQ-2026-0017', name: '精密检测仪', model: 'CMM-574 · 三坐标', category: '检测仪器', location: '质检中心 · 2F', owner: '李工', status: '运行中', date: '2025-07-26' },
  { id: 'EQ-2026-0016', name: '工业冷水机组', model: 'CW-180 · 变频型', category: '动力设备', location: '动力站 · 西侧', owner: '王工', status: '待维护', date: '2025-06-18' },
  { id: 'EQ-2026-0015', name: '自动贴片机', model: 'SMT-X8 · 高速型', category: '生产设备', location: '二号厂房 · C区', owner: '陈工', status: '运行中', date: '2025-05-30' },
  { id: 'EQ-2026-0014', name: '空气压缩机', model: 'AC-75 · 螺杆式', category: '动力设备', location: '动力站 · 东侧', owner: '赵工', status: '故障停机', date: '2025-04-11' },
  { id: 'EQ-2026-0013', name: '激光打标机', model: 'LM-30 · 光纤型', category: '生产设备', location: '一号厂房 · B区', owner: '周工', status: '运行中', date: '2025-03-08' },
])
const title = computed(() => menus.find(item => item.key === activeMenu.value)?.label ?? '设备管理系统')
const filteredDevices = computed(() => devices.value.filter(item => {
  const q = keyword.value.trim().toLowerCase()
  return (!q || `${item.id}${item.name}${item.model}${item.location}`.toLowerCase().includes(q)) && (statusFilter.value === '全部状态' || item.status === statusFilter.value)
}))
const displayName = computed(() => userStore.userInfo?.realName || userStore.userInfo?.username || '吴雪亚')
const clockText = computed(() => new Intl.DateTimeFormat('zh-CN', { year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false }).format(now.value).replace(/\//g, '年').replace(/年(\d{2})年/, '年$1月').replace(/年(\d{2}) /, '年$1日 '))
function chooseMenu(key: string) { activeMenu.value = key }
function savePassword() {
  if (!passwordForm.value.oldPassword || !passwordForm.value.newPassword) return ElMessage.warning('请完整填写密码信息')
  if (passwordForm.value.newPassword !== passwordForm.value.confirmPassword) return ElMessage.warning('两次输入的新密码不一致')
  ElMessage.success('密码修改申请已提交')
  changePasswordVisible.value = false
  passwordForm.value = { oldPassword: '', newPassword: '', confirmPassword: '' }
}
function addDevice() { ElMessage.info('设备新增表单已准备就绪') }
</script>

<template>
  <div class="device-system">
    <header class="system-header">
      <div class="header-brand"><div class="brand-symbol"><el-icon><Cpu /></el-icon></div><div><h1>设备管理系统</h1><span>EQUIPMENT MANAGEMENT SYSTEM</span></div></div>
      <div class="header-tools">
        <el-button text class="screen-link" @click="router.push('/dashboard')"><el-icon><Monitor /></el-icon>返回大屏</el-button>
        <i class="header-divider"></i>
        <el-dropdown trigger="click">
          <button class="account-button"><span class="account-avatar"><el-icon><User /></el-icon></span><span class="account-greeting"><b>{{ displayName }}</b>，您好！欢迎登录</span><el-icon class="caret"><CaretBottom /></el-icon></button>
          <template #dropdown><el-dropdown-menu><el-dropdown-item @click="changePasswordVisible = true"><el-icon><Lock /></el-icon>修改密码</el-dropdown-item><el-dropdown-item divided @click="userStore.logout()"><el-icon><User /></el-icon>退出登录</el-dropdown-item></el-dropdown-menu></template>
        </el-dropdown>
        <span class="header-time"><el-icon><Calendar /></el-icon>{{ clockText }}</span>
      </div>
    </header>
    <div class="system-body">
      <aside class="side-nav">
        <div class="nav-caption">功能导航 <span>MENU</span></div>
        <button v-for="item in menus" :key="item.key" class="nav-item" :class="{ active: activeMenu === item.key }" @click="chooseMenu(item.key)">
          <el-icon><component :is="item.icon" /></el-icon><span>{{ item.label }}</span><i v-if="item.badge" class="nav-badge">{{ item.badge }}</i><span v-if="activeMenu === item.key" class="active-indicator"></span>
        </button>
        <div class="sidebar-bottom"><div class="help-icon"><el-icon><ChatDotRound /></el-icon></div><div><b>需要帮助？</b><span>联系系统管理员获取支持</span></div></div>
      </aside>
      <main class="page-area">
        <div class="page-heading"><div><div class="breadcrumb">首页 <span>/</span> {{ title }}</div><h2>{{ title }}</h2><p>{{ activeMenu === 'overview' ? '查看设备运行情况与资产信息' : `管理和查看${title}相关信息` }}</p></div><div class="heading-actions"><el-button v-if="activeMenu === 'devices'" type="primary" @click="addDevice"><el-icon><Plus /></el-icon>新增设备</el-button><el-button v-else plain @click="activeMenu = 'devices'"><el-icon><Document /></el-icon>设备台账</el-button></div></div>

        <template v-if="activeMenu === 'overview'">
          <section class="summary-grid">
            <article class="summary-card"><div class="summary-top"><span>设备总数</span><i class="summary-icon blue"><el-icon><Monitor /></el-icon></i></div><strong>1,286</strong><small>较上月 <b>+ 28</b></small></article>
            <article class="summary-card"><div class="summary-top"><span>运行中</span><i class="summary-icon green"><el-icon><Cpu /></el-icon></i></div><strong>1,142</strong><small>设备运行率 <b>88.8%</b></small></article>
            <article class="summary-card"><div class="summary-top"><span>待维护</span><i class="summary-icon orange"><el-icon><Tools /></el-icon></i></div><strong>36</strong><small>本周计划 <b>12</b> 台</small></article>
            <article class="summary-card"><div class="summary-top"><span>故障设备</span><i class="summary-icon red"><el-icon><Warning /></el-icon></i></div><strong>8</strong><small>待处理告警 <b>3</b> 项</small></article>
          </section>
          <section class="content-card overview-table"><div class="section-heading"><div><h3>设备台账</h3><p>最近更新的设备信息</p></div><el-button text type="primary" @click="activeMenu = 'devices'">查看全部 <span class="arrow">→</span></el-button></div><DeviceTable :rows="devices.slice(0, 5)" /></section>
          <section class="info-grid"><article class="content-card status-card"><div class="section-heading"><div><h3>设备状态分布</h3><p>全量设备实时状态</p></div></div><div class="status-layout"><div class="donut"><div><b>1,286</b><span>设备总数</span></div></div><div class="status-legend"><div><i class="dot green-dot"></i><span>运行中</span><b>1,142</b><small>88.8%</small></div><div><i class="dot orange-dot"></i><span>待维护</span><b>136</b><small>10.6%</small></div><div><i class="dot red-dot"></i><span>故障停机</span><b>8</b><small>0.6%</small></div></div></div></article><article class="content-card activity-card"><div class="section-heading"><div><h3>近期动态</h3><p>设备管理最新操作记录</p></div><el-icon class="muted-icon"><Edit /></el-icon></div><div class="activity-list"><div><i class="activity-dot blue-dot"></i><p><b>新增设备</b><span>张工新增了数控加工中心 EQ-2026-0018</span><small>今天 10:24</small></p></div><div><i class="activity-dot green-dot"></i><p><b>完成保养</b><span>李工完成了精密检测仪的月度保养</span><small>今天 09:15</small></p></div><div><i class="activity-dot orange-dot"></i><p><b>维护提醒</b><span>工业冷水机组即将到达维护周期</span><small>昨天 16:42</small></p></div></div></article></section>
        </template>
        <template v-else-if="activeMenu === 'devices'"><section class="content-card list-card"><div class="filter-row"><div class="filter-title"><h3>设备台账</h3><span>共 {{ filteredDevices.length }} 台设备</span></div><div class="filters"><el-input v-model="keyword" placeholder="搜索设备名称、编号" clearable class="search-input"><template #prefix><el-icon><Search /></el-icon></template></el-input><el-select v-model="statusFilter" class="status-select"><el-option v-for="s in ['全部状态', '运行中', '待维护', '故障停机']" :key="s" :label="s" :value="s" /></el-select><el-button plain><el-icon><Download /></el-icon>导出</el-button></div></div><DeviceTable :rows="filteredDevices" /><div class="table-pagination"><span>显示 {{ filteredDevices.length ? 1 : 0 }}-{{ filteredDevices.length }} 条，共 {{ filteredDevices.length }} 条</span><div><button disabled>‹</button><button class="current-page">1</button><button disabled>›</button></div></div></section></template>
        <template v-else><section class="content-card empty-module"><div class="empty-icon"><el-icon><component :is="menus.find(item => item.key === activeMenu)?.icon" /></el-icon></div><h3>{{ title }}</h3><p>这里汇总设备{{ title }}信息，您可以通过左侧菜单继续浏览其他模块。</p><el-button type="primary" @click="activeMenu = 'devices'">查看设备台账</el-button></section></template>
        <footer class="page-footer"><span>© 2026 设备管理系统</span><span>设备全生命周期管理平台</span></footer>
      </main>
    </div>
    <el-dialog v-model="changePasswordVisible" title="修改密码" width="440px" class="password-dialog"><el-form label-position="top"><el-form-item label="当前密码"><el-input v-model="passwordForm.oldPassword" type="password" show-password placeholder="请输入当前密码" /></el-form-item><el-form-item label="新密码"><el-input v-model="passwordForm.newPassword" type="password" show-password placeholder="请输入新密码" /></el-form-item><el-form-item label="确认新密码"><el-input v-model="passwordForm.confirmPassword" type="password" show-password placeholder="请再次输入新密码" /></el-form-item></el-form><template #footer><el-button @click="changePasswordVisible = false">取消</el-button><el-button type="primary" @click="savePassword">确认修改</el-button></template></el-dialog>
  </div>
</template>

<script lang="ts">
import { defineComponent } from 'vue'
const DeviceTable = defineComponent({
  props: { rows: { type: Array, required: true } },
  template: `<div class="device-table-wrap"><table class="device-table"><thead><tr><th>设备编号</th><th>设备名称 / 型号</th><th>设备分类</th><th>所在位置</th><th>负责人</th><th>设备状态</th><th>购置日期</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td><span class="device-id">{{ row.id }}</span></td><td><b class="device-name">{{ row.name }}</b><small class="device-model">{{ row.model }}</small></td><td>{{ row.category }}</td><td>{{ row.location }}</td><td>{{ row.owner }}</td><td><span class="status-pill" :class="row.status === '运行中' ? 'status-running' : row.status === '待维护' ? 'status-maintenance' : 'status-fault'"><i></i>{{ row.status }}</span></td><td>{{ row.date }}</td></tr><tr v-if="!rows.length"><td colspan="7" class="no-data">没有找到匹配的设备</td></tr></tbody></table></div>`,
})
export default { components: { DeviceTable } }
</script>

